UnifiedEccWindow::UnifiedEccWindow(const RunConfig &base,QWidget *parent):QDialog(parent),fBase(base),fConnectionBase(base){
    setObjectName("UnifiedEccWindow");setWindowTitle(tr("ECC connections and services"));resize(1080,780);auto *layout=new QVBoxLayout(this);fTabs=new QTabWidget(this);layout->addWidget(fTabs);
    auto *existing=new QWidget(this);auto *page=new QVBoxLayout(existing);auto *help=new QLabel(tr("Connect to an ECC that is already running. Enter its computer IP and service port. Protocol details are detected automatically; checking a connection does not configure boards or start acquisition."),existing);help->setWordWrap(true);page->addWidget(help);
    auto *saved=new QComboBox(existing);saved->setObjectName("SavedEccConnections");saved->addItem(tr("New connection"),QString());auto knownProfiles=KnownEccConnectionProfiles();if(!base.filePath.isEmpty() && QFile::exists(base.filePath))knownProfiles.prepend(base.filePath);knownProfiles.removeDuplicates();for(const auto &path:knownProfiles.mid(0,64)){if(QFileInfo(path).size()>262144)continue;RunConfig c;QString error;if(!c.Load(path,&error))continue;const auto address=(c.nodes.isEmpty()?QString():c.nodes[0].host);const int port=(c.nodes.isEmpty()?0:c.nodes[0].eccPort);saved->addItem(QString("%1 — %2:%3").arg(c.eccName.isEmpty()?QFileInfo(path).baseName():c.eccName,address).arg(port),path);}page->addWidget(new QLabel(tr("Saved ECC connections"),existing));page->addWidget(saved);saved->setCurrentIndex(qMax(0,saved->findData(base.filePath)));
    auto *form=new QFormLayout;fName=new QLineEdit(tr("ECC"),existing);fName->setObjectName("ExistingEccName");fAddress=new QLineEdit("127.0.0.1",existing);fAddress->setObjectName("ExistingEccAddress");fPort=new QSpinBox(existing);fPort->setObjectName("ExistingEccPort");fPort->setRange(1,65535);fPort->setValue(8083);
    if(!base.simulation && !base.nodes.isEmpty()){fAddress->setText(base.nodes[0].host);fPort->setValue(base.nodes[0].eccPort);fName->setText(base.nodes[0].name);}
    if(!base.eccName.isEmpty())fName->setText(base.eccName);
    form->addRow(tr("Instance name"),fName);form->addRow(tr("ECC computer IP"),fAddress);form->addRow(tr("ECC service port"),fPort);page->addLayout(form);
    fAdvanced=new QCheckBox(tr("Existing receiver IP and data port"),existing);fAdvanced->setObjectName("ExistingEccAdvanced");page->addWidget(fAdvanced);auto *advanced=new QWidget(existing);auto *details=new QFormLayout(advanced);
    auto path=[&](const QString &label,const QString &name,bool directory){auto *row=new QWidget(advanced);auto *line=new QHBoxLayout(row);line->setContentsMargins(0,0,0,0);auto *edit=new QLineEdit(row);edit->setObjectName(name);auto *browse=new QPushButton(tr("Browse…"),row);line->addWidget(edit);line->addWidget(browse);details->addRow(label,row);connect(browse,&QPushButton::clicked,this,[this,edit,directory]{const auto value=directory?QFileDialog::getExistingDirectory(this,tr("Choose local data directory"),edit->text()):QFileDialog::getOpenFileName(this,tr("Choose saved GetDAQ connection"),edit->text(),tr("GetDAQ YAML (*.yml *.yaml)"));if(!value.isEmpty())edit->setText(value);});return edit;};
    fReceiver=new QLineEdit(advanced);fReceiver->setObjectName("ExistingEccReceiverAddress");fDataPort=new QSpinBox(advanced);fDataPort->setObjectName("ExistingEccDataPort");fDataPort->setRange(0,65535);fDataPort->setSpecialValueText(tr("Not configured"));details->addRow(tr("Data receiver IP (SOAP ECC)"),fReceiver);details->addRow(tr("Data receiver port (SOAP ECC)"),fDataPort);fOutput=path(tr("Local Run records directory"),"ExistingEccOutput",true);fOutput->setText(base.outputDir);
    if(!base.simulation && base.nodes.size()==1){fReceiver->setText(base.nodes[0].routerHost);fDataPort->setValue(base.nodes[0].routerPort);}
    auto *authNote=new QLabel(tr("Managed native ECC authorization is reused from saved profiles. An external protected ECC needs its authorized profile once. For new instances, use Create ECC / data services; no tokens or hashes need to be entered here."),advanced);authNote->setWordWrap(true);details->addRow(authNote);advanced->hide();page->addWidget(advanced);connect(fAdvanced,&QCheckBox::toggled,advanced,&QWidget::setVisible);
    fStatus=new QLabel(tr("Not checked. Select Check connection to read the ECC state."),existing);fStatus->setObjectName("ExistingEccStatus");fStatus->setWordWrap(true);page->addWidget(fStatus);auto *buttons=new QHBoxLayout;fCheck=new QPushButton(tr("Check connection"),existing);fCheck->setObjectName("CheckExistingEcc");fUse=new QPushButton(tr("Save and use in Run Setup"),existing);fUse->setObjectName("UseExistingEcc");fUse->setEnabled(false);fCancel=new QPushButton(tr("Stop waiting"),existing);fCancel->setObjectName("StopExistingEccWait");fCancel->setEnabled(false);buttons->addWidget(fCheck);buttons->addWidget(fUse);buttons->addWidget(fCancel);page->addLayout(buttons);page->addStretch();fTabs->addTab(existing,tr("Connect existing ECC"));
    fManaged=new DistributedDeploymentWindow(base,this);fManaged->setWindowFlags(Qt::Widget);fTabs->addTab(fManaged,tr("Create ECC / data services"));connect(fManaged,&QDialog::accepted,this,[this]{fSelected=fManaged->Configuration();accept();});connect(fManaged,&QDialog::rejected,this,[this]{QDialog::reject();});
    auto *close=new QPushButton(tr("Close (keep services running)"),this);layout->addWidget(close);connect(close,&QPushButton::clicked,this,&UnifiedEccWindow::RequestClose);connect(fCheck,&QPushButton::clicked,this,&UnifiedEccWindow::Check);connect(fUse,&QPushButton::clicked,this,&UnifiedEccWindow::Use);connect(fCancel,&QPushButton::clicked,this,[this]{if(fCanceled)fCanceled->store(true);fStatus->setText(tr("Stopping local waiting; the ECC service is unchanged."));});
    const auto changed=[this]{fUse->setEnabled(false);if(!fBusy)fStatus->setText(tr("Settings changed. Check the connection before saving."));};for(auto *edit:{fName,fAddress,fReceiver,fOutput})connect(edit,&QLineEdit::textChanged,this,changed);connect(fPort,QOverload<int>::of(&QSpinBox::valueChanged),this,changed);connect(fDataPort,QOverload<int>::of(&QSpinBox::valueChanged),this,changed);
    connect(saved,QOverload<int>::of(&QComboBox::currentIndexChanged),this,[this,saved](int index){if(fBusy)return;const auto path=saved->itemData(index).toString();RunConfig c=RunConfig::Default();QString error;if(!path.isEmpty() && !c.Load(path,&error)){fStatus->setText(error);return;}fConnectionBase=c;fName->setText(c.eccName.isEmpty()?QString("ECC"):c.eccName);fAddress->setText((!c.simulation && !c.nodes.isEmpty()?c.nodes[0].host:QString("127.0.0.1")));fPort->setValue((!c.simulation && !c.nodes.isEmpty()?c.nodes[0].eccPort:8083));fReceiver->setText(!c.simulation && !c.nodes.isEmpty()?c.nodes[0].routerHost:QString());fDataPort->setValue(!c.simulation && !c.nodes.isEmpty()?c.nodes[0].routerPort:0);fReceiver->setEnabled(true);fDataPort->setEnabled(true);fOutput->setText(c.outputDir);});
    connect(fTabs,&QTabWidget::currentChanged,this,[this](int index){if(fBusy)fTabs->setCurrentIndex(0);else if(fManaged->Busy())fTabs->setCurrentIndex(1);Q_UNUSED(index);});
}
bool UnifiedEccWindow::Busy() const{return fBusy || fManaged->Busy();}
QByteArray UnifiedEccWindow::Inputs() const{return Json({{"name",fName->text().trimmed()},{"address",fAddress->text().trimmed()},{"port",fPort->value()},{"profile",QString()},{"receiver",fReceiver->text().trimmed()},{"data_port",fDataPort->value()},{"output",fOutput->text().trimmed()}});}
void UnifiedEccWindow::Check(){
    if(Busy()){return;}
    fBusy=true;fCloseAfterWait=false;findChild<QComboBox *>("SavedEccConnections")->setEnabled(false);fUse->setEnabled(false);fCheck->setEnabled(false);fCancel->setEnabled(true);fCanceled=std::make_shared<std::atomic_bool>(false);const auto canceled=fCanceled;const auto name=fName->text().trimmed(),address=fAddress->text().trimmed(),profile=QString();const auto port=fPort->value();const auto base=fConnectionBase;const auto inputs=Inputs();const auto known=KnownEccConnectionProfiles();fStatus->setText(tr("Checking %1:%2… Only identity and state are queried.").arg(address).arg(port));
    auto *watcher=new QFutureWatcher<Result>(this);connect(watcher,&QFutureWatcher<Result>::finished,this,[this,watcher,inputs]{const auto result=watcher->result();watcher->deleteLater();fBusy=false;findChild<QComboBox *>("SavedEccConnections")->setEnabled(true);fCheck->setEnabled(true);fCancel->setEnabled(false);if(!result.second.isEmpty()){fStatus->setText(result.second);if(result.second.contains("profile",Qt::CaseInsensitive))fAdvanced->setChecked(true);}else if(Inputs()!=inputs){fStatus->setText(tr("Settings changed during the check. Check again before saving."));}else{fChecked=result.first;fReceiver->setEnabled(true);fDataPort->setEnabled(true);if(fOutput->text()==fBase.outputDir)fOutput->setText(fChecked.configuration.outputDir);if(fChecked.portChanged)fPort->setValue(fChecked.configuration.nodes[0].eccPort);fCheckedInputs=Inputs();fUse->setEnabled(true);fStatus->setText(tr("%1 ECC — %2\n%3").arg(tr("SOAP"),fChecked.status,fChecked.detail));}if(fCloseAfterWait)QDialog::reject();});watcher->setFuture(QtConcurrent::run([=]{OperationScope scope(canceled,20000);try{return qMakePair(CheckExistingEcc(name,address,port,base,known,profile),QString());}catch(const std::exception &error){return qMakePair(ExistingEccResult(),QString::fromUtf8(error.what()));}}));
}
void UnifiedEccWindow::Use(){
    if(Busy()){return;}
    try{Require(fUse->isEnabled() && Inputs()==fCheckedInputs,"Check the current settings before saving");auto config=fChecked.configuration;{config.nodes[0].routerPort=fDataPort->value();config.nodes[0].exporterPort=0;config.nodes[0].routerHost=fReceiver->text().trimmed();if(fDataPort->value())Address(config.nodes[0].routerHost);}if(!fOutput->text().trimmed().isEmpty())config.outputDir=fOutput->text().trimmed();const auto directory=QStandardPaths::writableLocation(QStandardPaths::AppLocalDataLocation)+"/connections/"+QUuid::createUuid().toString(QUuid::WithoutBraces);PrivateDirectory(directory);config.filePath=directory+"/envoy.yml";QString error;Require(config.Save(config.filePath,&error),error);Require(QFile::setPermissions(config.filePath,QFile::ReadOwner|QFile::WriteOwner),"Cannot protect the saved connection profile");RememberEccConnection(config.filePath);fSelected=config;accept();}catch(const std::exception &error){fStatus->setText(QString::fromUtf8(error.what()));}
}
void UnifiedEccWindow::RequestClose(){if(fBusy){fCloseAfterWait=true;if(fCanceled)fCanceled->store(true);fStatus->setText(tr("Stopping local waiting before closing."));return;}if(fManaged->Busy()){fManaged->RequestClose();return;}QDialog::reject();}
void UnifiedEccWindow::reject(){RequestClose();}
